// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    MyContract c;
    Rejector r;

    function setUp() public {
        c = new MyContract();
        r = new Rejector();
    }

    function testFuzz_property(uint256 amount, uint256 modeSeed) public {
        vm.assume(amount > 0 && amount < type(uint256).max / 2);
        bool shouldFail = modeSeed % 2 == 1;
        r.setShouldFail(shouldFail);
        vm.deal(address(c), amount);
        bool ok;
        try c.sendTo(address(r), amount) {
            ok = true;
        } catch {
            ok = false;
        }
        // General rule: whenever sendTo reports success, the counterparty must
        // have actually accepted and recorded exactly `amount` wei. The mutant
        // ignores the low-level call's failure flag, so with a rejecting
        // receiver it still returns success while nothing was received.
        assertTrue(!ok || (r.received() == amount));
    }
}

contract Rejector {
    bool public shouldFail;
    uint256 public received;

    function setShouldFail(bool f) external {
        shouldFail = f;
    }

    fallback() external payable {
        if (shouldFail) {
            revert();
        }
        received += msg.value;
    }

    receive() external payable {
        if (shouldFail) {
            revert();
        }
        received += msg.value;
    }
}
